mapper.select:
select o.id, user_id, u.username, operation, method, params, ip, status, error_msg, cost_time, o.create_time
from sys_operation_log o
left join sys_user u on o.user_id = u.id


        o.user_id = #{param.userId}


        and o.operation like concat('%', #{param.operation}, '%')


        and o.ip = #{param.ip}


        and o.status = #{param.status}


        and o.create_time between #{param.startTime} and #{param.endTime}


order by o.id desc
